using System;
using System.IO;
using System.Linq;
using System.Drawing;
using System.Collections.Generic;
using System.Reflection;
using System.Windows.Forms;

internal static class MotionEditingTests
{
    static void Check(bool value,string text){if(!value)throw new Exception(text);}
    static void Near(double a,double b,string text){Check(Math.Abs(a-b)<.002,text+": "+a+"/"+b);}
    static object Get(object obj,string field){return obj.GetType().GetField(field,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(obj);}
    static void Set(object obj,string field,object value){obj.GetType().GetField(field,BindingFlags.Instance|BindingFlags.NonPublic).SetValue(obj,value);}
    static object Call(object obj,string method,params object[] args){return obj.GetType().GetMethods(BindingFlags.Instance|BindingFlags.NonPublic).First(m=>m.Name==method&&m.GetParameters().Length==args.Length).Invoke(obj,args);}
    static Track Track(string id,int start,int end,int lane=0){return new Track{id=id,name=id,kind="emitter",start=start,end=end,lane=lane,x=300,y=200,count=1,interval=7,life=12,speed=0,advancedBullets=true};}
    static EditorState Scene(params Track[] tracks){var s=new EditorState{fps=50,duration=1000,tracks=tracks.ToList()};Motion.Normalize(s);return s;}
    static void Mouse(TimelineCanvas t,string method,int x,int y){Call(t,method,new MouseEventArgs(MouseButtons.Left,1,x,y,0));}
    static object Rows(BulletWorld w){return w.bullets.Where(b=>b.birth<=w.Frame&&!b.dead).Select(b=>new{source=b.source.id,b.birth,b.index,b.generation,b.x,b.y,b.direction,b.speed,scale=b.scale*BulletLifetime.Scale(b),alpha=b.alpha*BulletLifetime.Alpha(b),trailMode=Trails.Mode(b.source),trailInterval=b.source.trailInterval,trailLife=b.source.trailLife,trailAlpha=b.source.trailStartAlpha,trailSpeed=b.source.trailSpeed,trailDirection=b.source.trailDirection,trailRandom=b.source.trailRandom,b.kinematic,b.clockShift,b.sourceX,b.sourceY,b.collision}).ToArray();}
    static void InspectorImage(ParameterInspector inspector,string path)
    {var parent=inspector.Parent;var bounds=inspector.Bounds;var dock=inspector.Dock;parent.Controls.Remove(inspector);using(var surface=new Panel{Size=new Size(580,760),BackColor=Theme.Panel}){surface.Controls.Add(inspector);inspector.Dock=DockStyle.Fill;inspector.Visible=true;surface.CreateControl();inspector.CreateControl();surface.PerformLayout();using(var image=new Bitmap(surface.Width,surface.Height)){surface.DrawToBitmap(image,surface.ClientRectangle);image.Save(path);}surface.Controls.Remove(inspector);}parent.Controls.Add(inspector);inspector.Dock=dock;inspector.Bounds=bounds;}
    [STAThread] public static int Main(string[] args)
    {
        try {
            if(args[0]=="--samples"){
                var s=Json.Read<EditorState>(File.ReadAllText(args[1]));Motion.Normalize(s);var w=new BulletWorld(s);var samples=new Dictionary<string,object>();foreach(int f in args[2].Split(',').Select(Int32.Parse)){w.Seek(f);samples[f.ToString()]=new{bullets=Rows(w),globals=GlobalVariables.At(s,f)};}File.WriteAllText(args[3],Json.Write(samples));return 0;
            }
            {var longPath=Track("long-path",0,5100);MotionPresets.Apply(longPath,"圆周运动",0);TrackPreset.Validate(TrackPreset.Capture("long",new[]{longPath},50));var p=Motion.At(longPath,4000);Motion.At(longPath,4001);Check(!longPath.keyframes.Any(k=>k.property=="x"||k.property=="y"),"Long path created dense keys");Near(p.x,MotionPresets.Point(longPath.motionPreset,4000).X,"Long direct path");}
            string folder=args[0],root=args[1];Application.EnableVisualStyles();Language.Select(folder,"zh-CN");
            var fixture=Scene();fixture.duration=180;
            int index=0;foreach(string name in MotionPresets.Names){var t=Track("motion-"+index++,10,90,index);Motion.SetKey(t,"scale",10,.8);MotionPresets.Apply(t,name,10);Check(MotionPresets.Bound(t)&&t.motion=="keyframes","Preset binding missing");
                foreach(string field in new[]{"x","y"})Check(!t.keyframes.Any(k=>k.property==field),"Preset created position keys: "+name);
                for(int f=10;f<=90;f++){var point=MotionPresets.Point(t.motionPreset,f);var p=Motion.At(t,f);Near(p.x,point.X,"Baked X "+name);Near(p.y,point.Y,"Baked Y "+name);}
                Check(t.keyframes.Count(k=>k.property=="scale")==1,"Bake erased another property");var copy=t.Snapshot();copy.motionPreset.centerX+=20;Check(t.motionPreset.centerX!=copy.motionPreset.centerX&&copy.keyIndex==null,"Snapshot shares preset/cache");
                var preset=TrackPreset.Capture(name,new[]{t},50);var pasted=preset.Instantiate(100,100).Single();Check(!pasted.keyframes.Any(k=>k.property=="x"||k.property=="y")&&pasted.motionPreset.start==100&&pasted.motionPreset.end==260,"FPS conversion created keys or changed preset clock");fixture.tracks.Add(t);
            }
            {var old=Track("legacy-motion",10,90);MotionPresets.Apply(old,"圆周运动",10);for(int f=10;f<=90;f++){var p=MotionPresets.Point(old.motionPreset,f);old.keyframes.Add(new Keyframe{frame=f,property="x",value=p.X,easing="linear"});old.keyframes.Add(new Keyframe{frame=f,property="y",value=p.Y,easing="linear"});}var custom=old.Snapshot();custom.keyframes.Single(k=>k.property=="x"&&k.frame==45).value+=9;Scene(custom);Check(!MotionPresets.Bound(custom)&&custom.keyframes.Single(k=>k.property=="x"&&k.frame==45).value!=MotionPresets.Point(old.motionPreset,45).X,"Modified legacy motion key was discarded");Motion.SetKey(old,"alpha",45,.4);var s=Scene(old);Check(old.keyframes.Count==1&&old.keyframes[0].property=="alpha","Legacy position keys were not removed or a manual key was lost");Check(CursorSnapping.Capture(s,old,0,true)(44)==null&&CursorSnapping.Capture(s,old,0,true)(45)==45,"Preset samples interfere with cursor snapping");}
            {var a=Track("held",150,190);var b=Track("victim",100,240);b.motion="velocity";b.velocityX=2;var s=Scene(a,b);Check(TimelineLayout.CutOverlaps(s,new[]{a}),"Cut failed");Motion.Normalize(s);var pieces=s.tracks.Where(t=>t.clipSourceId==b.id).OrderBy(t=>t.start).ToArray();Check(pieces.Length==2&&pieces[0].start==100&&pieces[0].end==149&&pieces[1].start==191&&pieces[1].end==240,"Middle overwrite did not keep both sides");Near(Motion.At(pieces[1],200).x,500,"Trimmed movement restarted");Check(a.start==150&&a.end==190&&a.lane==0,"Overwrite displaced held clip");}
            {var a=Track("held",50,150);var b=Track("covered",70,90);var c=Track("other-lane",70,90,1);var s=Scene(a,b,c);TimelineLayout.CutOverlaps(s,new[]{a});Check(!s.tracks.Any(t=>t.id==b.id)&&s.tracks.Contains(c),"Full cover/cross-lane cut is wrong");}
            {var parent=new Track{id="group",kind="group",name="group",start=0,end=100,lane=0};var child=Track("child",0,100,1);child.parentId=parent.id;var a=Track("held",40,60);var s=Scene(parent,child,a);TimelineLayout.CutOverlaps(s,new[]{a});Motion.Normalize(s);Check(s.tracks.Count(t=>t.kind=="group")==2&&s.tracks.Count(t=>t.clipSourceId==child.id)==2,"Group split lost a child");foreach(var t in s.tracks.Where(t=>t.clipSourceId==child.id))Check(t.parent!=null&&t.start==t.parent.start&&t.end==t.parent.end,"Group split parent IDs/bounds diverged");}
            {var original=Track("referenced",0,100);var caller=Track("caller",0,100,2);caller.spawnActions.Add(new BulletAction{type="spawn",templateId=original.id});var held=Track("held",20,80);var s=Scene(original,caller,held);TimelineLayout.CutOverlaps(s,new[]{held});Check(s.tracks.Single(t=>t.id==original.id).templateOnly&&s.tracks.Single(t=>t.id==original.id).end==100,"Overwrite damaged a shared template definition");}
            {var a=Track("dragged",0,40);var b=Track("behind",100,240);var s=Scene(a,b);using(var timeline=new TimelineCanvas{State=s,Size=new Size(1600,400),PixelsPerSecond=250,ClipSnap=false}){
                timeline.CreateControl();timeline.SetTrackSelection(new[]{a},a);timeline.RefreshLayout();var bar=timeline.ClipBounds(a);int x=(int)(bar.X+bar.Width/2),y=(int)bar.Y+10,begins=0,changes=0;timeline.BeginEdit=()=>begins++;timeline.Changed=()=>changes++;
                Mouse(timeline,"OnMouseDown",x,y);Mouse(timeline,"OnMouseMove",x+750,y);Near(timeline.ClipBounds(a).Y,bar.Y,"Held clip jumped vertically at overlap");Mouse(timeline,"OnMouseMove",x+775,y);Mouse(timeline,"OnMouseMove",x+750,y);Check(b.end==240&&a.lane==0,"Drag mutates other clips or changes lane before release");Mouse(timeline,"OnMouseUp",x+750,y);Check(a.start==150&&begins==1&&changes==1&&s.tracks.Count==3,"Overwrite gesture did not commit once");
            }}
            {var a=Track("snap-a",0,20);var b=Track("snap-b",100,180);var c=Track("snap-c",250,300,1);var s=Scene(a,b,c);using(var timeline=new TimelineCanvas{State=s,Size=new Size(1800,400),PixelsPerSecond=250}){
                timeline.CreateControl();timeline.SetTrackSelection(new[]{a},a);timeline.RefreshLayout();var r=timeline.ClipBounds(a);int x=(int)(r.X+r.Width/2),y=(int)r.Y+10;Mouse(timeline,"OnMouseDown",x,y);Mouse(timeline,"OnMouseMove",x+900,y);Check(a.start==181&&a.lane==0,"Same-lane end did not snap into adjacency");Mouse(timeline,"OnMouseUp",x+900,y);
                timeline.SetTrackSelection(new[]{a},a);r=timeline.ClipBounds(a);x=(int)(r.X+r.Width/2);y=(int)r.Y+10;Mouse(timeline,"OnMouseDown",x,y);Mouse(timeline,"OnMouseMove",x+342,y);Check(a.start==250,"Cross-lane edges do not align");Mouse(timeline,"OnMouseUp",x+342,y);var view=timeline.CaptureView();view.clipSnap=false;timeline.RestoreView(view);Check(!timeline.ClipSnap,"Edge snapping preference did not restore");
            }}
            using(var form=new MainForm(folder)){var t=Track("ui-circle",10,90);MotionPresets.Apply(t,"圆周运动",10);var s=Scene(t);var doc=new LoadData{state=s,room=new RoomData(),inventory=new Inventory{sprites=new[]{"sprBullet"},objects=new string[0],scripts=new string[0],rooms=new[]{"rAvoidance"},objectSprites=new Dictionary<string,string>()},waveform=new WaveData{duration=20,peaks=new double[100]}};Set(form,"state",s);Set(form,"document",doc);var timeline=(TimelineCanvas)Get(form,"timeline");timeline.State=s;Call(form,"SelectTrack",t,null);var properties=(ParameterInspector)Get(form,"properties");var bag=(NativeProperties)properties.SelectedObject;Check(bag.GetProperties()["X"].IsReadOnly&&bag.GetProperties()["Y"].IsReadOnly&&(string)bag.GetProperties()["X"].GetValue(bag)=="由预设控制"&&bag.GetProperties()["运动中心 X"]!=null,"Inspector does not show preset-controlled X/Y");Call(form,"PushUndo");bag.GetProperties()["运动半径"].SetValue(bag,120.0);Near(Motion.At(t,10).x,t.motionPreset.centerX+120,"Parameter edit did not update the path");InspectorImage(properties,Path.Combine(folder,"motion-inspector-zh.png"));Language.Select(folder,"en");Language.Apply(form);Call(form,"ShowProperties");InspectorImage(properties,Path.Combine(folder,"motion-inspector-en.png"));Language.Select(folder,"zh-CN");Call(form,"Undo",false);Check(((EditorState)Get(form,"state")).tracks.Single().motionPreset.radiusStart==100,"Undo lost preset parameters");
                var a=Track("undo-held",0,40);var b=Track("undo-cut",100,240);s=Scene(a,b);Set(form,"state",s);doc.state=s;timeline.State=s;timeline.ClipSnap=false;timeline.Size=new Size(1600,400);timeline.PixelsPerSecond=250;Call(form,"SelectTrack",a,null);timeline.RefreshLayout();var r=timeline.ClipBounds(a);int x=(int)(r.X+r.Width/2),y=(int)r.Y+10;Mouse(timeline,"OnMouseDown",x,y);Mouse(timeline,"OnMouseMove",x+750,y);Mouse(timeline,"OnMouseUp",x+750,y);Check(s.tracks.Count==3,"UI overwrite did not split");Call(form,"Undo",false);s=(EditorState)Get(form,"state");Check(s.tracks.Count==2&&s.tracks.Single(row=>row.id==a.id).start==0&&s.tracks.Single(row=>row.id==b.id).end==240&&((Track)Get(form,"selectedTrack")).id==a.id,"Single undo did not restore overwrite and selection");
            }
            // Native fixture: baked paths plus overwritten emission, variables, groups and clips.
            var crop=Track("crop-source",10,90,20);crop.motion="velocity";crop.velocityX=1.2;crop.angle=30;crop.expressions["speed"]=".1*age";Motion.SetKey(crop,"y",10,180);Motion.SetKey(crop,"y",90,260);var mask=Track("cut-mask",30,50,20);mask.enabled=false;fixture.tracks.AddRange(new[]{crop,mask});Motion.Normalize(fixture);TimelineLayout.CutOverlaps(fixture,new[]{mask});fixture.tracks.Remove(mask);
            var negative=fixture.tracks.Single(t=>t.clipSourceId==crop.id&&t.start==51).Snapshot();negative.id="negative-clock";negative.start-=51;negative.end-=51;TimelineLayout.ShiftClock(negative,-51);foreach(var key in negative.keyframes)key.frame-=51;negative.x=650;negative.lane=21;fixture.tracks.Add(negative);
            fixture.tracks.AddRange(new[]{new Track{id="phase",kind="variable",lane=30,start=0,end=120,variableName="phase",variableExpression="45"},new Track{id="counter",kind="variable",lane=31,start=51,end=120,clockStart=0,clockEnd=120,variableName="counter",variableExpression="age",variableRepeat=10},new Track{id="distance",kind="variable",lane=32,start=0,end=0,variableName="distance",variableExpression="5"}});
            var control=new Track{id="control",kind="control",start=65,end=65,lane=33,targetSource=crop.id,controlAction="direction",controlValue=150};fixture.tracks.Add(control);
            var clip=new Track{id="cut-pattern",name="pattern",kind="pattern",start=35,end=100,clockStart=0,clockEnd=100,lane=40,repeatCount=4,children=new List<Track>{Track("inside",0,20)}};fixture.tracks.Add(clip);Motion.Normalize(fixture);File.WriteAllText(Path.Combine(folder,"scene.json"),Json.Write(fixture));
            var expanded=BulletSystem.Expand(fixture);Check(expanded.tracks.Where(t=>t.id.StartsWith("cut-pattern/")).All(t=>t.start>=35&&t.end<=100),"Pattern trim expanded outside retained range");
            Console.WriteLine("PASS: 14 parameter-driven motion presets, legacy sample migration, snapping, inspector, snapshot/undo/FPS, overwrite drag, group/shared-template cuts, motion clocks and adjacency snapping; native fixture exported.");return 0;
        }catch(Exception error){Console.Error.WriteLine(error);return 1;}
    }
}
